"""SFMC academy content: 28 modules. Each topic follows the prompt's teaching structure (condensed).

Verify current Salesforce product names, editions, licences and certification names on the official Salesforce pages
before publishing; this file states them as general guidance, not as a current price or catalogue.
"""

def T(t, what, why, how, example, mistake, interview, links, exercise, code=None, licence=None):
    return dict(t=t, what=what, why=why, how=how, example=example, mistake=mistake, interview=interview,
                links=links, exercise=exercise, code=code, licence=licence)

